### **1. `BattleSystem`**  
*Manages turn-based combat, party/enemy state, and victory conditions.*  
**Return Type:** `BattleSystem` (singleton instance)  

```csharp
public class BattleSystem : MonoBehaviour
{
    // Properties (Variables)
    public int CurrentTurn { get; private set; }
    public List<Character> ActiveParty { get; private set; }
    public List<Character> Enemies { get; private set; }
    public bool IsBattleActive { get; private set; }
    public BattleState CurrentState { get; private set; }

    // Events for Unity UI integration
    public UnityEvent OnTurnStart = new UnityEvent();
    public UnityEvent OnBattleEnd = new UnityEvent();

    // Constructor (Singleton pattern)
    public static BattleSystem Instance { get; private set; }

    // Methods
    public bool StartBattle(List<Character> party, List<Character> enemies)
    {
        if (party.Count == 0 || enemies.Count == 0) return false;
        ActiveParty = party;
        Enemies = enemies;
        IsBattleActive = true;
        CurrentState = BattleState.Ongoing;
        CurrentTurn = 0;
        SortTurnOrder(); // Sorts by Speed stat
        OnTurnStart.Invoke();
        return true;
    }

    public void MoveTurn()
    {
        CurrentTurn++;
        if (CurrentTurn >= ActiveParty.Count + Enemies.Count)
        {
            CurrentTurn = 0; // Reset to first unit
        }
        OnTurnStart.Invoke();
    }

    public bool CheckVictory()
    {
        bool partyVictory = !ActiveParty.Any(c => c.IsAlive);
        bool enemyVictory = !Enemies.Any(c => c.IsAlive);
        if (partyVictory || enemyVictory)
        {
            CurrentState = partyVictory ? BattleState.Victory : BattleState.Defeat;
            IsBattleActive = false;
            OnBattleEnd.Invoke();
            return true;
        }
        return false;
    }

    private void SortTurnOrder()
    {
        ActiveParty.Sort((a, b) => b.Speed.CompareTo(a.Speed));
        Enemies.Sort((a, b) => b.Speed.CompareTo(a.Speed));
    }

    public enum BattleState { Ongoing, Victory, Defeat }
}
```

