### **2. `Character`**  
*Base class for all playable/enemy units (e.g., player, NPC, boss).*  
**Return Type:** `Character` (extended by subclasses like `Player` or `Enemy`)

```csharp
[System.Serializable]
public class Character : MonoBehaviour
{
    // Properties (Variables)
    public string Name { get; set; }
    public int MaxHealth { get; set; }
    public int CurrentHealth { get; private set; }
    public int Attack { get; set; }
    public int Defense { get; set; }
    public int Magic { get; set; }
    public int Speed { get; set; }
    public List<StatusEffect> StatusEffects { get; private set; } = new List<StatusEffect>();
    public List<Item> Inventory { get; private set; } = new List<Item>();
    public bool IsAlive => CurrentHealth > 0;

    // Methods
    public void TakeDamage(int amount)
    {
        int actualDamage = Mathf.Max(1, amount - Defense);
        CurrentHealth -= actualDamage;
        if (CurrentHealth <= 0) CurrentHealth = 0;
    }

    public bool UseSkill(Skill skill, List<Character> targets)
    {
        if (!skill.CheckRequirements(this)) return false;
        int damage = skill.Execute(this, targets);
        skill.Cooldown = skill.BaseCooldown;
        return true;
    }

    public void UseItem(Item item)
    {
        item.Use(this);
        Inventory.Remove(item);
    }

    public void ApplyStatusEffect(StatusEffect effect)
    {
        if (effect.Duration > 0) StatusEffects.Add(effect);
    }

    public void UpdateStatusEffects()
    {
        for (int i = StatusEffects.Count - 1; i >= 0; i--)
        {
            StatusEffects[i].Duration--;
            if (StatusEffects[i].Duration <= 0)
            {
                StatusEffects.RemoveAt(i);
            }
        }
    }
}
```

