### **3. `Skill`**  
*Represents abilities like fireballs, sword slashes, or hacking.*  
**Return Type:** `Skill` (used via `Character.UseSkill()`)

```csharp
[System.Serializable]
public class Skill : MonoBehaviour
{
    // Properties (Variables)
    public string Name { get; set; }
    public string Description { get; set; }
    public int Cost { get; set; }
    public int BaseCooldown { get; set; }
    public int CurrentCooldown { get; set; }
    public int Range { get; set; }
    public TargetType TargetType { get; set; }
    public DamageType DamageType { get; set; }

    // Methods
    public bool CheckRequirements(Character user)
    {
        return user.Magic >= Cost && CurrentCooldown <= 0;
    }

    public int Execute(Character user, List<Character> targets)
    {
        int totalDamage = CalculateBaseDamage(user);
        foreach (Character target in targets)
        {
            target.TakeDamage(totalDamage);
        }
        return totalDamage;
    }

    private int CalculateBaseDamage(Character user)
    {
        return (user.Attack * 1.5f) + (user.Magic * 0.5f);
    }

    public enum TargetType { Single, Area, Self, All }
    public enum DamageType { Physical, Magic, Energy }
}
```

