### **4. `Item`**  
*Base class for consumables (potions) and gear (weapons/armor).*  
**Return Type:** `Item` (extended by subclasses like `Potion` or `Weapon`)

```csharp
[System.Serializable]
public abstract class Item : MonoBehaviour
{
    // Properties (Variables)
    public string Name { get; set; }
    public string Description { get; set; }
    public ItemType Type { get; set; }

    // Methods
    public virtual void Use(Character user)
    {
        // Override in subclasses (e.g., heal, apply buff)
    }

    public enum ItemType { Consumable, Weapon, Armor, Utility }
}

// Example: Potion (subclassed)
public class Potion : Item
{
    public int HealAmount { get; set; }

    public override void Use(Character user)
    {
        user.CurrentHealth = Mathf.Min(user.MaxHealth, user.CurrentHealth + HealAmount);
    }
}
