### **5. `Party`**  
*Manages player-controlled teams (e.g., 3–4 members).*  
**Return Type:** `Party` (used by `BattleSystem`)

```csharp
public class Party : MonoBehaviour
{
    // Properties (Variables)
    public List<Character> Members { get; private set; } = new List<Character>();
    public Character Leader { get; set; }

    // Methods
    public void AddMember(Character character)
    {
        Members.Add(character);
        character.IsAlive = true;
    }

    public void RemoveMember(Character character)
    {
        Members.Remove(character);
    }

    public Dictionary<string, float> GetTotalStats()
    {
        var stats = new Dictionary<string, float>
        {
            ["MaxHealth"] = 0,
            ["Attack"] = 0,
            ["Defense"] = 0,
            ["Magic"] = 0,
            ["Speed"] = 0
        };

        foreach (var member in Members)
        {
            stats["MaxHealth"] += member.MaxHealth;
            stats["Attack"] += member.Attack;
            stats["Defense"] += member.Defense;
            stats["Magic"] += member.Magic;
            stats["Speed"] += member.Speed;
        }
        return stats;
    }
}
```

