### **6. `StatusEffect`**  
*Applies temporary buffs/debuffs (e.g., "Burn," "Stun").*  
**Return Type:** `StatusEffect` (handled via `Character.UpdateStatusEffects()`)

```csharp
[System.Serializable]
public class StatusEffect : MonoBehaviour
{
    // Properties (Variables)
    public string Name { get; set; }
    public int Duration { get; set; }
    public float Modifier { get; set; }
    public StatusType Type { get; set; }

    // Methods
    public void ApplyTo(Character target)
    {
        switch (Type)
        {
            case StatusType.HealthDebuff:
                target.CurrentHealth = Mathf.Max(1, target.CurrentHealth - (int)Modifier);
                break;
            case StatusType.DamageBuff:
                target.Attack += (int)Modifier;
                break;
        }
    }

    public enum StatusType { HealthDebuff, DamageBuff, SpeedBuff, Stun }
}
```

